from PIL import Image
import numpy as np
im = np.array(Image.open('mol_0023.png').convert('L'))<128
def scan(y0,y1,x0,x1,step=3):
    for y in range(y0,y1,step):
        xs=np.where(im[y,x0:x1])[0]+x0
        groups=[]
        for x in xs:
            if groups and x-groups[-1][-1]<=1: groups[-1].append(x)
            else: groups.append([x])
        print(y,[(int(g[0]),int(g[-1])) for g in groups])
print('--- S region')
scan(240,320,300,480)
